using System;using System.Data;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class PermissionMatrixPage:UserControl{readonly string[] roles={"Recruiter","Employer","Candidate"};readonly string[] perms={"Dashboard.View","Jobs.View","Jobs.Manage","Candidates.View","Candidates.Manage","Applications.View","Applications.Manage","Companies.View","Companies.Manage","Users.Manage"};ComboBox role;CheckedListBox list;public PermissionMatrixPage(){BackColor=Theme.Background;Padding=new Padding(12);var head=Ui.Label(L.Fa?"ماتریس دسترسی نقش‌ها":"Role permission matrix",18,true);head.Dock=DockStyle.Top;head.Height=45;Controls.Add(head);var card=Ui.Card();card.Dock=DockStyle.Fill;Controls.Add(card);role=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=220,Left=24,Top=30};role.Items.AddRange(roles);role.SelectedIndexChanged+=(s,e)=>LoadRole();card.Controls.Add(role);list=new CheckedListBox{Left=24,Top=78,Width=520,Height=390,CheckOnClick=true,Font=new Font("Segoe UI",10)};list.Items.AddRange(perms);card.Controls.Add(list);var save=Ui.Button(L.Fa?"ذخیره دسترسی‌ها":"Save permissions");save.Left=24;save.Top=485;save.Click+=(s,e)=>Save();card.Controls.Add(save);role.SelectedIndex=0;}void LoadRole(){for(int i=0;i<list.Items.Count;i++)list.SetItemChecked(i,false);var t=Database.Query("SELECT PermissionKey FROM RolePermissions WHERE RoleName=@r AND IsAllowed=1",new SqlParameter("@r",role.Text));foreach(DataRow row in t.Rows){int i=list.Items.IndexOf(Convert.ToString(row[0]));if(i>=0)list.SetItemChecked(i,true);}}void Save(){if(!AppSession.IsAdmin)return;Database.Exec("DELETE FROM RolePermissions WHERE RoleName=@r",new SqlParameter("@r",role.Text));foreach(var x in list.CheckedItems)Database.Exec("INSERT RolePermissions(RoleName,PermissionKey,IsAllowed) VALUES(@r,@p,1)",new SqlParameter("@r",role.Text),new SqlParameter("@p",x.ToString()));Database.Audit("PermissionUpdate","Role",role.Text);MessageBox.Show(L.Fa?"دسترسی‌ها ذخیره شد.":"Permissions saved.");}}
}
